-- ============================================================
-- V2.1 — Catálogo base (roles, usuarios demo, marca, categorías,
-- subcategorías, atributos y los 5 polos con 40 variantes).
--
-- Este contenido antes lo creaba DataInitializer.java en tiempo de
-- ejecución, pero SOLO en el perfil "dev" y DESPUÉS de que Flyway ya
-- corría — por eso nunca existía en un entorno realmente nuevo (qa/
-- prod/Neon), y V3 (que asume que la marca id=1 y los productos 1-5
-- ya existen) fallaba con violación de foreign key. Al convertirlo en
-- una migración SQL corre igual en cualquier entorno. Se inserta con
-- versión "2.1" (entre V2 y V3) para respetar el orden de dependencia
-- que V3 ya asume.
--
-- Todo el bloque va guardado detrás de un IF NOT EXISTS (igual que
-- DataInitializer.java lo hacía) para que sea seguro re-aplicar esta
-- migración vía out-of-order en una base local que YA tiene estos
-- datos cargados por DataInitializer en una sesión anterior — evita
-- duplicar filas o violar constraints de PK en ese caso.
-- ============================================================

DO $migration$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM roles LIMIT 1) THEN


  END IF;
END
$migration$;

-- Sincroniza las secuencias con los IDs explícitos insertados arriba
-- (idempotente: no rompe nada si ya estaban en estos valores).
SELECT setval('roles_id_seq', 3, true);
SELECT setval('users_id_seq', 3, true);
SELECT setval('companies_id_seq', 1, true);
SELECT setval('company_user_id_seq', 2, true);
SELECT setval('attribute_types_id_seq', 5, true);
SELECT setval('attribute_values_id_seq', 15, true);
SELECT setval('brands_id_seq', 1, true);
SELECT setval('categories_id_seq', 3, true);
SELECT setval('subcategories_id_seq', 4, true);
SELECT setval('products_id_seq', 5, true);
SELECT setval('variant_products_id_seq', 40, true);
